import{_ as a,C as i,o as l,c as n,ak as r,E as o,j as t,a as c}from"./chunks/framework.DxrHb2fb.js";const f=JSON.parse('{"title":"Timer 计时器","description":"","frontmatter":{},"headers":[],"relativePath":"components/timer.md","filePath":"components/timer.md","lastUpdated":1790400917000}'),s={name:"components/timer.md"};function h(b,d,p,m,u,g){const e=i("XhDemo");return l(),n("div",null,[d[0]||(d[0]=r('<h1 id="timer-计时器" tabindex="-1">Timer 计时器 <a class="header-anchor" href="#timer-计时器" aria-label="Permalink to &quot;Timer 计时器&quot;">​</a></h1><p>一段可正计时或倒计时的时长：可启动、暂停、继续、归零。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/timer" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/timer.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/timer" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/timer" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/timer.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>一个自动递增的秒表：不写内容时组件铺设时、分、秒三段，auto-start 使它挂载即开始运行</p>',5)),o(e,{src:"timer/01-basic"}),d[1]||(d[1]=r('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;timer&quot;</code>：<strong><code>root</code></strong> · <strong><code>display</code></strong> · <code>item</code> · <code>separator</code> · <code>control</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="倒计时" tabindex="-1">倒计时 <a class="header-anchor" href="#倒计时" aria-label="Permalink to &quot;倒计时&quot;">​</a></h3><p>countdown 使它从起始值递减，终点默认是 0；到达终点即停在该处不再递减</p>',6)),o(e,{src:"timer/02-countdown"}),d[2]||(d[2]=t("h3",{id:"起停与归零",tabindex:"-1"},[c("起停与归零 "),t("a",{class:"header-anchor",href:"#起停与归零","aria-label":'Permalink to "起停与归零"'},"​")],-1)),d[3]||(d[3]=t("p",null,"自行编写部件：control 是一个原生按钮，按一下即按当前状态前进一步（开始 / 暂停 / 继续 / 重来）",-1)),o(e,{src:"timer/03-control"}),d[4]||(d[4]=t("h3",{id:"带天数的长计时",tabindex:"-1"},[c("带天数的长计时 "),t("a",{class:"header-anchor",href:"#带天数的长计时","aria-label":'Permalink to "带天数的长计时"'},"​")],-1)),d[5]||(d[5]=t("p",null,"小时满 24 会进位到天，超过一天的计时要自行编写一段 days，只写时分秒会丢失整天数",-1)),o(e,{src:"timer/04-days"}),d[6]||(d[6]=t("h3",{id:"三个尺寸档",tabindex:"-1"},[c("三个尺寸档 "),t("a",{class:"header-anchor",href:"#三个尺寸档","aria-label":'Permalink to "三个尺寸档"'},"​")],-1)),d[7]||(d[7]=t("p",null,"size 只写在 root 上，数字大小与起停按钮的高度一起换档，子部件不重复标注",-1)),o(e,{src:"timer/05-size"}),d[8]||(d[8]=t("h3",{id:"每一拍与到期",tabindex:"-1"},[c("每一拍与到期 "),t("a",{class:"header-anchor",href:"#每一拍与到期","aria-label":'Permalink to "每一拍与到期"'},"​")],-1)),d[9]||(d[9]=t("p",null,"tick 每过一个 interval 触发一次，complete 只在到达终点时触发一次；到期的一拍不再触发 tick",-1)),o(e,{src:"timer/06-notify"}),d[10]||(d[10]=t("h3",{id:"受控通道",tabindex:"-1"},[c("受控通道 "),t("a",{class:"header-anchor",href:"#受控通道","aria-label":'Permalink to "受控通道"'},"​")],-1)),d[11]||(d[11]=t("p",null,"提供 value 与 active 后进入受控分支：value 改写即重新计时，active 切换为假停在当前剩余量、切换为真继续运行",-1)),o(e,{src:"timer/07-controlled"}),d[12]||(d[12]=r('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>秒表、答题计时、专注计时等需要用户自行控制起停的场景。</li><li>会议或直播的已进行时长。</li><li>需要倒计时且中途可暂停的限时任务。</li><li>验证码重发倒计时、限时活动、会话即将过期提醒等只倒数、不需要按钮的场景：使用受控通道，只提供剩余时长。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>展示一个时刻而不是一段时长时，使用<a href="./timestamp">时间戳</a>。</li><li>表达任务完成到哪一步时，使用<a href="./progress">进度条</a>。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>正计时或倒计时由 <code>countdown</code> 决定，起点 <code>startMs</code> 与终点 <code>targetMs</code> 两个方向共用。</li><li><code>start</code> / <code>pause</code> / <code>resume</code> / <code>reset</code> 四个动作齐全，<code>control</code> 部件把它们收成一个按钮，按当前状态自动切换语义。</li><li>时间只由单调时钟的两个时刻相减得出，不逐拍累加，因此频繁起停也不会累积偏差。</li><li><code>interval</code> 只决定数字的刷新频率；到点由另一个精确落在终点的定时器判定，终点不在整拍上也不会走过头。</li><li>每一段数字是一个 <code>item</code> 部件，<code>unit</code> 说明它是天、时、分、秒还是毫秒，排版完全由作者决定。</li><li>受控通道：提供 <code>value</code>（剩余毫秒）或 <code>active</code> 即进入受控分支。<code>value</code> 即起点，方向锁定为倒计时，终点锁定为 0，改写它即从新值重新计时；<code>active</code> 为假时停在当前值，为真时继续。受控时起停按钮不再改变状态（根上落 <code>data-controlled</code>），状态由这两个 prop 决定。</li><li><code>format</code> 把当前值格式化为字符串（<code>api.text</code>），<code>precision</code> 决定精确到哪一位：<code>0</code> 到秒、<code>3</code> 到毫秒，默认 <code>3</code> 即不量化。</li><li><code>live</code> 决定时间区的读屏播报档位，默认 <code>off</code>。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h3><ul><li>与<a href="./button">按钮</a>配合组成“开始 / 暂停 / 重来”一排控制。</li><li>与<a href="./progress">进度条</a>并排，一个表示剩余时长，一个表示完成比例。</li><li>结束后用<a href="./alert">警告提示</a>或<a href="./toast">轻提示</a>告知用户下一步。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>计时超过一天时自行增加 <code>days</code> 段：<code>hours</code> 满 24 会进位到天，只写时分秒会丢失整天数。</li><li>数字使用等宽字形，位数变化时分隔符才不会左右移动；皮肤已经如此处理，自定义排版时保留。</li><li>嵌在一句话内或放在其他数值槽中时把 <code>--xh-timer-digit-font-size</code> 写为 <code>inherit</code>，数字跟随上下文字号，不再使用展示档字号。</li><li>精确到秒的倒计时不开启高频播报，读屏用户会被持续打断。</li><li>每一段的数字始终由组件写入条目，作者只声明该段的单位；写在条目内的内容不会保留，下一拍会被新的数字覆盖。需要在数字旁加字（“时”“分”）时写进记号部件。</li><li>起停按钮的名称（读屏读出的）始终由组件按当前状态提供，切换语言使用 <code>translations</code>，不硬编码。按钮内显示的文字两个适配器不同，见下一条。</li><li>两个适配器的差别只有三处，编写标记前先核对： <ul><li>默认结构：Vue 的根组件不写内容时自动铺开“时:分:秒”；Web Components 侧元素不生成任何结构，root 与 display 缺一不可，每一段与记号都由作者编写。</li><li>按钮内的文字：Vue 的起停按钮不写内容时填当前动作的名称（Start / Pause / Resume / Reset）；Web Components 侧的文字由作者编写（多为图标），元素只切换按钮的 <code>data-action</code> 与读屏名称。</li><li>记号的默认值：Vue 的记号部件不写内容时是冒号；Web Components 侧记号内的文字一律由作者编写。</li></ul></li><li>Web Components 侧条目上的 <code>unit</code> 是作者的声明、不是元素写回的状态，改动它本身不会触发重新接线：停止时改动需要等下一次属性变更或启动后才生效（运行时每一拍都会重新接线）。</li><li>结束后要有明确的去处：归零重来，或跳转到下一步，不停留在 00:00。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>用它显示当前时刻：它只处理时长，不处理日历与时区。</li><li>只提供终点而不提供起点做倒计时：起点默认为 0，倒计时一启动就到点，屏幕上始终是 00:00。倒计时长需要写进 <code>startMs</code>。</li><li>挂载后再改 <code>autoStart</code> 期望它启动：该 prop 只在挂载时读取一次，起停请使用动作或 <code>control</code>。</li><li>结束后没有任何反馈。</li><li>结束后停在 00:00，既不归零也不提供下一步。</li><li>页面切到后台后计时漂移却不校正：时间只由单调时钟的两个时刻相减，不自行按拍累加。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-timer&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhTimerControl</code> <code>XhTimerDisplay</code> <code>XhTimerItem</code> <code>XhTimerRoot</code> <code>XhTimerSeparator</code></td></tr><tr><td>组合式函数</td><td><code>useTimer</code></td></tr><tr><td>状态机</td><td><code>timerMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/timer.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>startMs</code></td><td><code>number</code></td><td></td><td>起始值毫秒，默认 0。正计时从它向上走，倒计时从它向下走。</td></tr><tr><td><code>targetMs</code></td><td><code>number</code></td><td></td><td>终点值毫秒。倒计时默认 0；正计时未提供时持续运行，没有终点也不会通知完成。 终点落在起点的反方向（倒计时提供了比起点更大的终点）时本轮长度为 0： 显示值停在起点上，一开始运行即到期。</td></tr><tr><td><code>countdown</code></td><td><code>boolean</code></td><td></td><td>倒计时，默认假。</td></tr><tr><td><code>value</code></td><td><code>number</code></td><td></td><td>受控剩余毫秒。提供后即进入受控通道：它就是起点，方向锁定为倒计时、终点锁定为 0， startMs / targetMs / countdown 三者不再参与；改写它即把累计清零并从新值重新计时。</td></tr><tr><td><code>active</code></td><td><code>boolean</code></td><td></td><td>受控开关，默认真。提供后即进入受控通道：变为假时停在当前累计值，变为真时从该处继续。 受控时起停按钮不再改变状态：状态由该 prop 决定。</td></tr><tr><td><code>autoStart</code></td><td><code>boolean</code></td><td></td><td>挂载即开始运行，默认假。它只在挂载时读取一次，之后修改不再生效。</td></tr><tr><td><code>interval</code></td><td><code>number</code></td><td></td><td>刷新间隔毫秒，默认 1000，下限一帧。 它只决定数字的跳动间隔；到期由另一个精确落在终点上的定时器判定，不受它影响。</td></tr><tr><td><code>format</code></td><td><code>string</code></td><td></td><td>文本模板，默认 <code>HH:mm:ss</code>。D 天、H 时、m 分、s 秒、S 毫秒，重复字母的个数即最少位数。</td></tr><tr><td><code>precision</code></td><td><code>number</code></td><td></td><td>取值粒度：0 到秒、1 到十分之一秒、2 到百分之一秒、3 到毫秒。默认 3，即不量化。</td></tr><tr><td><code>live</code></td><td><code>TimerLive</code></td><td></td><td>读屏播报档位，默认 off。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;TimerTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>onTick</code></td><td><code>(details: TimerTickDetails) =&gt; void</code></td><td></td><td>每一拍通知一次。到期的一拍只发 onComplete。</td></tr><tr><td><code>onComplete</code></td><td><code>(details: TimerCompleteDetails) =&gt; void</code></td><td></td><td>到达终点时通知一次；中途被暂停或归零不通知。</td></tr></tbody></table><h3 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h3><p>自定义元素将载荷放在 <code>detail</code>；Vue 使用同名 emit。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>tick</code></td><td><code>TimerTickDetails</code></td><td>经过一拍；detail 为 <code>{ value: number, elapsed: number }</code></td></tr><tr><td><code>complete</code></td><td><code>TimerCompleteDetails</code></td><td>到达终点；detail 为 <code>{ value: number, elapsed: number }</code></td></tr></tbody></table><h3 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h3><p>仅列出带载荷的插槽。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhTimerRoot</code></td><td><code>default</code></td><td><code>TimerRootSlotProps</code></td><td></td></tr></tbody></table><h3 id="react-适配器-props" tabindex="-1">React 适配器 props <a class="header-anchor" href="#react-适配器-props" aria-label="Permalink to &quot;React 适配器 props&quot;">​</a></h3><p>只列各组件自己声明的那些：继承自 <code>ComponentPropsWithRef</code> 的 DOM 属性不在其中，根组件上与上面 Props 表同名的也不重复列。Vue 的对应物是上面的插槽表。</p><table tabindex="0"><thead><tr><th>React 组件</th><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>XhTimerItem</code></td><td><code>unit</code></td><td><code>TimerUnit</code></td><td>是</td><td>该段的单位。</td></tr><tr><td><code>XhTimerRoot</code></td><td><code>children</code></td><td><code>SlotChildren&lt;TimerRootSlotProps&gt;</code></td><td></td><td></td></tr></tbody></table><h3 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h3><p>公开状态写入 <code>data-state</code>。</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;idle&#39; | &#39;running&#39; | &#39;paused&#39; | &#39;completed&#39;</td></tr><tr><td><code>display</code></td><td>&#39;idle&#39; | &#39;running&#39; | &#39;paused&#39; | &#39;completed&#39;</td></tr></tbody></table><p>以下名称仅用于内部状态机。</p><p><strong>状态</strong>：<code>idle</code> · <code>running</code> · <code>paused</code> · <code>completed</code></p><p><strong>事件</strong>：<code>RUN.START</code> · <code>RUN.PAUSE</code> · <code>RUN.RESUME</code> · <code>RUN.RESET</code> · <code>CLOCK.TICK</code> · <code>CLOCK.SETTLE</code> · <code>CLOCK.SYNC</code> · <code>PRESS.START</code> · <code>PRESS.END</code></p><p><strong>判据</strong>：<code>isSettled</code></p><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>phase</code></td><td><code>TimerPhase</code></td><td></td></tr><tr><td><code>value</code></td><td><code>number</code></td><td>当前应显示的毫秒，已夹在起点与终点之间并按 precision 量化。</td></tr><tr><td><code>text</code></td><td><code>string</code></td><td>按模板格式化的文本，即不自行排列各段时应显示的文字。</td></tr><tr><td><code>controlled</code></td><td><code>boolean</code></td><td>是否使用受控通道：提供了 value 或 active 即是，此时起停按钮不改变状态。</td></tr><tr><td><code>elapsed</code></td><td><code>number</code></td><td>累计经过的毫秒，与方向和起始值无关。</td></tr><tr><td><code>running</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>paused</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>completed</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>countdown</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>segments</code></td><td><code>TimerSegments</code></td><td>显示值拆开的五段。</td></tr><tr><td><code>segmentText</code></td><td><code>(unit: TimerUnit) =&gt; string</code></td><td>某一段补零后的字面：天不补零，时分秒两位，毫秒三位。</td></tr><tr><td><code>controlAction</code></td><td><code>TimerControlAction</code></td><td>起停按钮本次的动作。</td></tr><tr><td><code>controlLabel</code></td><td><code>string</code></td><td>起停按钮的读屏名字，也是按钮内未写内容时应显示的文字。</td></tr><tr><td><code>start</code></td><td><code>() =&gt; void</code></td><td>从头开始运行。</td></tr><tr><td><code>pause</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>resume</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>reset</code></td><td><code>() =&gt; void</code></td><td>归零并停止。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getDisplayProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>(props: TimerItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getSeparatorProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getControlProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/button/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Enter</code> / <code>Space</code></td><td>focus on control</td><td>按当前状态起停：没起步的开跑、在走的暂停、停在半路的接着走、走完的归零；control 是原生 button，这两个键由平台翻成 click</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>held on control</td><td>按住期间 control 投影 data-pressed，与指针 :active 同一副按压面（text 档定尺按钮，按下缩放并换底）；抬起或失焦撤下。按钮没有禁用态，四段状态下都接，按住途中起停翻转按压面不丢</td></tr></tbody></table><h3 id="aria" tabindex="-1">ARIA <a class="header-anchor" href="#aria" aria-label="Permalink to &quot;ARIA&quot;">​</a></h3><p>以下属性由 <code>connect</code> 生成。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>display</code></td><td><code>aria-label</code></td><td>label.time(segments)</td></tr><tr><td><code>display</code></td><td><code>aria-live</code></td><td>props.live</td></tr><tr><td><code>display</code></td><td><code>role</code></td><td>&#39;timer&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>separator</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>control</code></td><td><code>aria-label</code></td><td>label[controlAction]</td></tr></tbody></table><ul><li>时间区带有整段时间的读屏名称，其中的数字与记号对读屏隐藏。</li><li>内建名称始终按“时 分 秒”读出（天数大于 0 时前面再加天）。屏幕上只放了其中几段（例如只有分和秒）时会多读一段，请用 <code>translations.time</code> 按实际段数提供名称。</li><li>内建名称是英文，切换语言同样使用 <code>translations.time</code>。</li><li>默认不播报。需要播报的场景（会话到期提醒等）把 <code>live</code> 设为 <code>polite</code> 或 <code>assertive</code>，或在外层另起一个 live 区域，只在关键节点播报一句：每秒变化的数字按 polite 播报，一分钟就是六十次打断。</li></ul><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/timer.css</code> 使用 <code>[data-scope=&quot;timer&quot;][data-part=&quot;root&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-controlled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-countdown</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;idle&#39; | &#39;running&#39; | &#39;paused&#39; | &#39;completed&#39;</td></tr><tr><td><code>display</code></td><td><code>data-state</code></td><td>&#39;idle&#39; | &#39;running&#39; | &#39;paused&#39; | &#39;completed&#39;</td></tr><tr><td><code>item</code></td><td><code>data-unit</code></td><td>item.unit</td></tr><tr><td><code>control</code></td><td><code>data-action</code></td><td>&#39;pause&#39; | &#39;resume&#39; | &#39;reset&#39; | &#39;start&#39;</td></tr><tr><td><code>control</code></td><td><code>data-pressed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>control</code></td><td><code>data-xh-action-control</code></td><td>&#39;&#39;</td></tr><tr><td><code>control</code></td><td><code>data-xh-action-display</code></td><td>&#39;always&#39;</td></tr><tr><td><code>control</code></td><td><code>data-xh-action-profile</code></td><td>&#39;text&#39;</td></tr><tr><td><code>control</code></td><td><code>data-xh-action-size</code></td><td>props.size</td></tr><tr><td><code>control</code></td><td><code>data-xh-action-variant</code></td><td>&#39;outline&#39;</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；默认来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>默认来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-timer-completed-fg</code></td><td><code>display</code></td><td><code>color</code></td><td><code>state=completed</code></td><td><code>--xh-fg-muted</code></td><td>timer 的 display 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-timer-control-bg</code></td><td><code>control</code></td><td><code>--xh-ink-surface</code><br><code>background-color</code></td><td><code>default</code><br><code>xh-ink-surface</code></td><td><code>--xh-_action-variant-bg-rest</code></td><td>timer 的 control 部件 --xh-ink-surface、background-color 覆盖槽。</td></tr><tr><td><code>--xh-timer-control-bg-active</code></td><td><code>control</code></td><td><code>background-color</code></td><td><code>disabled</code><br><code>is(:active, [data-pressed])</code><br><code>loading</code><br><code>not([data-disabled])</code><br><code>not([data-loading])</code><br><code>pressed</code></td><td><code>--xh-_action-variant-bg-pressed</code></td><td>timer 的 control 部件 background-color 覆盖槽。</td></tr><tr><td><code>--xh-timer-control-bg-disabled</code></td><td><code>control</code></td><td><code>--xh-ink-surface</code><br><code>background-color</code></td><td><code>disabled</code><br><code>xh-ink-surface</code></td><td><code>--xh-_action-variant-bg-disabled</code></td><td>timer 的 control 部件 --xh-ink-surface、background-color 覆盖槽。</td></tr><tr><td><code>--xh-timer-control-bg-hover</code></td><td><code>control</code></td><td><code>background-color</code></td><td><code>disabled</code><br><code>hover</code><br><code>loading</code><br><code>not([data-disabled])</code><br><code>not([data-loading])</code></td><td><code>--xh-_action-variant-bg-hover</code></td><td>timer 的 control 部件 background-color 覆盖槽。</td></tr><tr><td><code>--xh-timer-control-border</code></td><td><code>control</code></td><td><code>border</code></td><td><code>default</code></td><td><code>--xh-_action-variant-border-rest</code></td><td>timer 的 control 部件 border 覆盖槽。</td></tr><tr><td><code>--xh-timer-control-border-disabled</code></td><td><code>control</code></td><td><code>border-color</code></td><td><code>disabled</code></td><td><code>--xh-_action-variant-border-disabled</code></td><td>timer 的 control 部件 border-color 覆盖槽。</td></tr><tr><td><code>--xh-timer-control-border-focus</code></td><td><code>control</code></td><td><code>border-color</code></td><td><code>focus-visible</code></td><td><code>--xh-_action-variant-border-focus-visible</code></td><td>timer 的 control 部件 border-color 覆盖槽。</td></tr><tr><td><code>--xh-timer-control-border-hover</code></td><td><code>control</code></td><td><code>border-color</code></td><td><code>disabled</code><br><code>hover</code><br><code>is(:active, [data-pressed])</code><br><code>loading</code><br><code>not([data-disabled])</code><br><code>not([data-loading])</code><br><code>pressed</code></td><td><code>--xh-_action-variant-border-hover</code><br><code>--xh-_action-variant-border-pressed</code></td><td>timer 的 control 部件 border-color 覆盖槽。</td></tr><tr><td><code>--xh-timer-control-fg</code></td><td><code>control</code></td><td><code>color</code></td><td><code>default</code><br><code>disabled</code><br><code>hover</code><br><code>is(:active, [data-pressed])</code><br><code>loading</code><br><code>not([data-disabled])</code><br><code>not([data-loading])</code><br><code>pressed</code></td><td><code>--xh-_action-variant-fg-hover</code><br><code>--xh-_action-variant-fg-pressed</code><br><code>--xh-_action-variant-fg-rest</code></td><td>timer 的 control 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-timer-control-gap</code></td><td><code>control</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-_action-profile-gap</code></td><td>timer 的 control 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-timer-control-h</code></td><td><code>control</code></td><td><code>block-size</code></td><td><code>default</code></td><td><code>--xh-_action-profile-visual-size</code></td><td>timer 的 control 部件 block-size 覆盖槽。</td></tr><tr><td><code>--xh-timer-control-px</code></td><td><code>control</code></td><td><code>padding-inline</code></td><td><code>default</code></td><td><code>--xh-_action-profile-padding-inline</code></td><td>timer 的 control 部件 padding-inline 覆盖槽。</td></tr><tr><td><code>--xh-timer-control-radius</code></td><td><code>control</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-control</code></td><td>timer 的 control 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-timer-control-shadow-active</code></td><td><code>control</code></td><td><code>box-shadow</code></td><td><code>disabled</code><br><code>is(:active, [data-pressed])</code><br><code>loading</code><br><code>not([data-disabled])</code><br><code>not([data-loading])</code><br><code>pressed</code></td><td><code>none</code></td><td>timer 的 control 部件 box-shadow 覆盖槽。</td></tr><tr><td><code>--xh-timer-control-shadow-hover</code></td><td><code>control</code></td><td><code>box-shadow</code></td><td><code>disabled</code><br><code>hover</code><br><code>loading</code><br><code>not([data-disabled])</code><br><code>not([data-loading])</code></td><td><code>none</code></td><td>timer 的 control 部件 box-shadow 覆盖槽。</td></tr><tr><td><code>--xh-timer-digit-font-size</code></td><td><code>display</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-_timer-digit-size</code></td><td>timer 的 display 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-timer-display-fg</code></td><td><code>display</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-default</code></td><td>timer 的 display 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-timer-fg</code></td><td><code>root</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-default</code></td><td>timer 的 root 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-timer-gap</code></td><td><code>root</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-_timer-gap</code></td><td>timer 的 root 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-timer-icon-size</code></td><td><code>control</code></td><td><code>--xh-icon-size</code></td><td><code>default</code></td><td><code>--xh-_action-profile-glyph-size</code></td><td>timer 的 control 部件 --xh-icon-size 覆盖槽。</td></tr><tr><td><code>--xh-timer-item-fg</code></td><td><code>item</code></td><td><code>color</code></td><td><code>default</code></td><td><code>inherit</code></td><td>timer 的 item 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-timer-separator-fg</code></td><td><code>separator</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-subtle</code></td><td>timer 的 separator 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-timer-separator-px</code></td><td><code>separator</code></td><td><code>padding-inline</code></td><td><code>default</code></td><td><code>--xh-space-0_5</code></td><td>timer 的 separator 部件 padding-inline 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p>动效角色：按压 · 状态（见<a href="./../design/motion#角色">动效规范</a>）。</p><p><code>color</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h3 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h3><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><ul><li>时间区的排列方向固定为从左到右，<code>&lt;html dir=&quot;rtl&quot;&gt;</code> 下时分秒不会倒序排列，时间串的读序在两个方向相同。</li><li>起停按钮相对时间区的位置，以及整个组件在页面内的排布，照常跟随文字方向。</li></ul>',61))])}const v=a(s,[["render",h]]);export{f as __pageData,v as default};
